    h, w = len(grid), len(grid[0])
    # Find the repeated, filled color strip (each row contains the same sequence).
    seen=set(); strips=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in comp); r1=max(y for y,x in comp)
            c0=min(x for y,x in comp); c1=max(x for y,x in comp)
            hh,ww=r1-r0+1,c1-c0+1
            if hh>=2 and ww>=2 and len(comp)==hh*ww:
                seq=[grid[r0][x] for x in range(c0,c1+1)]
                if all([grid[y][x] for x in range(c0,c1+1)] == seq for y in range(r0,r1+1)):
                    strips.append((len(comp),r0,r1,c0,c1,seq))
    if not strips:
        return [row[:] for row in grid]
    _,pr0,pr1,pc0,pc1,colors=max(strips)
    # The central object has the color at the strip's center position.
    color=colors[len(colors)//2]
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r,c) in seen or (pr0<=r<=pr1 and pc0<=c<=pc1):
