                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objects.append(comp)
    if not objects:
        return [row[:] for row in grid]
    shape=max(objects,key=len)
    top=min(y for y,x in shape); left=min(x for y,x in shape)
    bottom=max(y for y,x in shape); right=max(x for y,x in shape)
    pattern=[(y-top,x-left) for y,x in shape]
    dh=bottom-top+1
    original_index=colors.index(color)
    out=[[0]*w for _ in range(h)]
    for i,new_color in enumerate(colors):
        dy=top+(i-original_index)*dh
        for oy,ox in pattern:
            y,x=dy+oy,left+ox
            if 0<=y<h and 0<=x<w: out[y][x]=new_color
    return out
